const crypto = require('crypto');
const accessKey = 'yCrnfHeNp7sKC5h3';
const secretKey = 'Em2sPDj0VaRGvnnY';
const baseUrl = 'https://metersphere.devops.moego.pet';
const timestamp = Date.now();
const uuid = crypto.randomUUID();
const comboxKey = `${accessKey}|${uuid}|${timestamp}`;
const key = Buffer.from(secretKey.slice(0, 16), 'utf-8');
const iv = Buffer.from(accessKey.slice(0, 16), 'utf-8');
const cipher = crypto.createCipheriv('aes-128-cbc', key, iv);
let encrypted = cipher.update(comboxKey, 'utf-8', 'base64');
encrypted += cipher.final('base64');
const caseId = $input.first().json.case_id;
if (!caseId) throw new Error('case_id is required');
return [{ json: { baseUrl, caseId, headers: { 'Content-Type': 'application/json', 'ACCEPT': 'application/json', 'accessKey': accessKey, 'signature': encrypted } } }];

const response = $input.first().json;
if (!response.success) throw new Error(`MeterSphere API error: ${response.message}`);
const c = response.data;
return [{ json: { id: c.id, num: c.num, name: c.name, node_path: c.nodePath, project_id: c.projectId, type: c.type, priority: c.priority, status: c.status, review_status: c.reviewStatus, maintainer: c.maintainer, create_user: c.createUser, step_model: c.stepModel, prerequisite: c.prerequisite || '', step_description: c.stepDescription || '', expected_result: c.expectedResult || '', steps: c.steps || '[]', remark: c.remark || '', tags: c.tags || '[]', demand_name: c.demandName || '', issues: (c.issueList || []).map(i => ({ id: i.id, title: i.title, platform: i.platform, status: i.platformStatus })), create_time: c.createTime ? new Date(c.createTime).toISOString() : null, update_time: c.updateTime ? new Date(c.updateTime).toISOString() : null } }];
